import arrtForm from "./components/modelMapping/arrtForm";
import editCom from "./components/modelMapping/edit";
import checkCom from "./components/modelMapping/check";
import { globalattrSearch, globalattrDel, cmdbciattrList, i6000ciattrList, i6000Mapping, checkRefresh, mxRefresh, cmdbGetList } from "@/api/system/modelMapping";
export default {
  components: {
    arrtForm: arrtForm,
    editCom: editCom,
    checkCom: checkCom
  },
  data: function data() {
    return {
      currentItem: {},
      cmdbCiIdList: [],
      lll: [{
        dictKey: 1,
        dictValue: '手工录入'
      }, {
        dictKey: 2,
        dictValue: '枚举数据'
      }, {
        dictKey: 3,
        dictValue: '配置类型'
      }, {
        dictKey: 4,
        dictValue: '外部数据'
      }],
      cmdbAttrCodeList: [],
      i6000AttrCodeList: [],
      searchForm: {
        current: 1,
        size: 15,
        cmdbCiName: undefined,
        cmdbAttrCode: undefined,
        i6000AttrCode: undefined
      },
      total: 0,
      tableData: [],
      tableHeight: undefined,
      tableLoading: false,
      // 弹窗
      showForm: false,
      showForm2: false,
      showType: '',
      arrtId: '',
      cmdbMxObj: null,
      tbmxLoading: false,
      tbysLoading: false
    };
  },
  mounted: function mounted() {
    this.setPageContentHeight();
    this.setTableHeight();
    this.getDict();
    this.getList();
  },
  methods: {
    cmdbCiIdChange: function cmdbCiIdChange(val) {
      var _this = this;
      this.searchForm.cmdbAttrCode = undefined;
      this.searchForm.i6000AttrCode = undefined;
      var obj = this.cmdbCiIdList.filter(function (el) {
        return el.cmdbCiName == val;
      })[0];
      this.cmdbMxObj = obj;
      cmdbciattrList({
        size: 500,
        current: 1,
        ciId: obj.cmdbCiId
      }).then(function (res) {
        _this.cmdbAttrCodeList = res.data.records;
      });
      i6000ciattrList({
        size: 500,
        current: 1,
        ciCode: obj.i6000CiId
      }).then(function (res) {
        _this.i6000AttrCodeList = res.data.records;
      });
    },
    changeStatus: function changeStatus(row) {
      if (row.i6000OriType === '1') {
        return "手工录入";
      } else if (row.i6000OriType === '2') {
        return "枚举数据";
      } else if (row.i6000OriType === '3') {
        return "配置类型";
      } else if (row.i6000OriType === '4') {
        return "外部数据";
      }
    },
    showDictLable: function showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code !== '') {
        var items = dictList.filter(function (item) {
          return item.dictKey == code;
        });
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    },
    handleQuery: function handleQuery() {
      this.searchForm.current = 1;
      this.getList();
    },
    haldleSync: function haldleSync(type) {
      var _this2 = this;
      if (!this.cmdbMxObj) {
        this.$alert('请先选择cmdb模型', '提醒', {
          confirmButtonText: this.$t("submitText"),
          cancelButtonText: this.$t("cancelText"),
          type: "warning"
        });
        return;
      }
      if (type == 'tbmx') {
        this.tbmxLoading = true;
        mxRefresh({
          ciCode: this.cmdbMxObj ? this.cmdbMxObj['i6000CiId'] : null
        }).then(function (res) {
          _this2.$message.success('同步模型请求成功');
        }).finally(function () {
          _this2.tbmxLoading = false;
        });
      } else if (type == 'tbys') {
        this.tbysLoading = true;
        checkRefresh(this.cmdbMxObj).then(function (res) {
          _this2.$message.success('同步映射关系请求成功');
        }).finally(function () {
          _this2.tbysLoading = false;
        });
      }
    },
    handleReset: function handleReset() {
      this.searchForm.cmdbAttrCode = undefined;
      this.searchForm.i6000AttrCode = undefined;
      this.getList();
    },
    getDict: function getDict() {
      var _this3 = this;
      i6000Mapping().then(function (res) {
        _this3.cmdbCiIdList = res.data;
      });
    },
    // 设置表格高度
    setTableHeight: function setTableHeight() {
      var bodyBox = document.getElementsByClassName('page_body');
      this.tableHeight = bodyBox[0].offsetHeight - 50 + 'px';
    },
    getList: function getList() {
      var _this4 = this;
      this.tableLoading = true;
      cmdbGetList(this.searchForm).then(function (res) {
        _this4.tableData = res.data;
        // this.total = res.data.total;
        _this4.tableLoading = false;
      }).catch(function () {
        _this4.tableLoading = false;
      });
    },
    // 删除
    delArrt: function delArrt(row) {
      var _this5 = this;
      this.$confirm('确定是否删除?', '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning'
      }).then(function () {
        globalattrDel({
          id: row.id
        }).then(function (res) {
          _this5.$message({
            type: 'success',
            message: '删除成功！'
          });
          _this5.getList();
        });
      });
    },
    // 编辑
    editArrt: function editArrt(row) {
      this.showType = '修改';
      this.arrtId = row.id;
      this.currentItem = row;
      this.showForm = true;
    },
    saveGlobalArrt: function saveGlobalArrt() {
      this.showForm = false;
      this.getList();
    }
  }
};
